                                <Button Name="btnOpenDeviceManager" Content="M&#x1EDF; Tr&#x00EC;nh Qu&#x1EA3;n L&#x00FD; Device Manager" Style="{StaticResource SecondaryButton}" Margin="0,3" HorizontalContentAlignment="Left" Padding="14,9"/>
