                                    if (-not $unlockState.Deleted) {
                                        $rbInner = 0
                                        $unlockState.Deleted = [DuckUtil.DeepUninstallerEngine]::ForceDeleteDirectory($ci.Path, [ref]$rbInner)
                                        $unlockState.RebootCount = $rbInner
                                    }
                                }.GetNewClosure()
                                $deletedOk = [bool]$unlockState.Deleted
                                $rebootTotal += [int]$unlockState.RebootCount
                            }
                        }

                        if (-not $deletedOk) {
                            $rbCount = 0
                            if ($hasForceDelAsync) {
                                $dTask = $deepType::ForceDeleteDirectoryAsync($ci.Path, (-not $useForceStop))
                                [void](Wait-TaskNonBlocking -Task $dTask -TimeoutSeconds 60)
                                if ($dTask.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion -and $null -ne $dTask.Result) {
                                    $deletedOk = [bool]$dTask.Result.Deleted
                                    $rbCount = [int]$dTask.Result.RebootScheduledCount
                                }
                            } else {
                                $hasFastForceDel = @([DuckUtil.DeepUninstallerEngine].GetMethods() | Where-Object { $_.Name -eq "ForceDeleteDirectory" -and $_.GetParameters().Count -eq 3 }).Count -gt 0
                                if ($hasFastForceDel) {
                                    $deletedOk = [DuckUtil.DeepUninstallerEngine]::ForceDeleteDirectory($ci.Path, (-not $useForceStop), [ref]$rbCount)
                                } else {
                                    $deletedOk = [DuckUtil.DeepUninstallerEngine]::ForceDeleteDirectory($ci.Path, [ref]$rbCount)
                                }
                            }
                            $rebootTotal += $rbCount
                        }

                        if ($deletedOk) {
                            $removed++
                            $freed += $ci.SizeBytes
                            if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
                                Log-Text "[D$([char]0x1ECC)N R$([char]0x00C1)C] $([char]0x0110)$([char]0x00E3) d$([char]0x1ECD)n s$([char]0x1EA1)ch: $($ci.Type) - $($ci.Path)"
                            }
                        }
                    }
                } catch {
                    if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
                        Log-Text "[!] L$([char]0x1ED7)i khi x$([char]0x00F3)a $($ci.Path): $($_.Exception.Message)"
                    }
                }
            }

            if ($rebootTotal -gt 0 -and (Get-Command Log-Text -ErrorAction SilentlyContinue)) {
                Log-Text "[*] $([char]0x0110)$([char]0x00E3) $([char]0x0111)$([char]0x1EB7)t l$([char]0x1ECB)ch x$([char]0x00F3)a $rebootTotal file $([char]0x0111)ang b$([char]0x1ECB) kh$([char]0x00F3)a ngay khi Windows kh$([char]0x1EDF)i $([char]0x0111)$([char]0x1ED9)ng l$([char]0x1EA1)i (MoveFileEx)."
            }
            if (($accessDeniedTotal -gt 0 -or $rebootTotal -gt 0) -and (Get-Command Log-Text -ErrorAction SilentlyContinue)) {
                Log-Text "[!] L$([char]0x01B0)u $([char]0x00FD): T$([char]0x1EC7)p b$([char]0x1ECB) kh$([char]0x00F3)a b$([char]0x1EDF)i driver b$([char]0x1EA3)o v$([char]0x1EC7) c$([char]0x1EA5)p nh$([char]0x00E2)n (nh$([char]0x01B0) 360) kh$([char]0x00F4)ng th$([char]0x1EC3) t$([char]0x1EAF)t t$([char]0x1EEB) Windows th$([char]0x01B0)$([char]0x1EDD)ng; h$([char]0x00E3)y t$([char]0x1EAF)t T$([char]0x1EF1) b$([char]0x1EA3)o v$([char]0x1EC7) trong app, ch$([char]0x1EA1)y l$([char]0x1EA1)i trong Safe Mode ho$([char]0x1EB7)c kh$([char]0x1EDF)i $([char]0x0111)$([char]0x1ED9)ng l$([char]0x1EA1)i $([char]0x0111)$([char]0x1EC3) MoveFileEx d$([char]0x1ECD)n."
            }

            $dialogResult.Confirmed = $true
            $dialogResult.RemovedCount = $removed
            $dialogResult.FreedBytes = $freed
            $dialogResult.RebootScheduled = $rebootTotal
            $dialogResult.AccessDeniedCount = $accessDeniedTotal
            $dialog.Close()
        } finally {
            $btnDelete.IsEnabled = $true
            if ($btnCancel) { $btnCancel.IsEnabled = $true }
            if ($btnSelectAll) { $btnSelectAll.IsEnabled = $true }
            if ($btnDeselectAll) { $btnDeselectAll.IsEnabled = $true }
        }
    })
    $btnStack.Children.Add($btnDelete) | Out-Null

    [System.Windows.Controls.Grid]::SetColumn($btnStack, 1)
    $bottomGrid.Children.Add($btnStack) | Out-Null

    $bottomBar.Child = $bottomGrid
    [System.Windows.Controls.Grid]::SetRow($bottomBar, 2)
    $rootGrid.Children.Add($bottomBar) | Out-Null

    $dialog.Content = $rootGrid
    if (-not $script:isWindowClosing) {
        try {
            $null = $dialog.ShowDialog()
        } catch {} finally {
            try { $dialog.Owner = $null } catch {}
        }
    }

    return $dialogResult
}

function Resolve-SilentUninstallPlan {
    param(
        [Parameter(Mandatory = $true)]$AppEntry,
        [bool]$AutoSilent = $true
    )

    $hasExplicitQuiet = -not [string]::IsNullOrWhiteSpace($AppEntry.QuietUninstallString)
    $hasStandardUninstall = -not [string]::IsNullOrWhiteSpace($AppEntry.UninstallString)
    $usedExplicitQuietFallback = $false
    $rawCmd = if ($AutoSilent) {
        if ($hasExplicitQuiet) {
            $AppEntry.QuietUninstallString.Trim()
        } elseif ($hasStandardUninstall) {
            $AppEntry.UninstallString.Trim()
        } else {
            ""
        }
    } else {
        if ($hasStandardUninstall) {
            $AppEntry.UninstallString.Trim()
        } elseif ($hasExplicitQuiet) {
            $usedExplicitQuietFallback = $true
            $AppEntry.QuietUninstallString.Trim()
        } else {
            ""
        }
    }

    if ([string]::IsNullOrWhiteSpace($rawCmd)) {
        return [PSCustomObject]@{
            Mode                = "None"
            Exe                 = ""
            Args                = ""
            Framework           = ""
            AddedSilentFlags    = $false
            IsSilent            = $false
            IsLikelyDarkPattern = $false
        }
    }

    if ($rawCmd.IndexOf("msiexec", [System.StringComparison]::OrdinalIgnoreCase) -ge 0) {
        $msiId = if (Get-Command Get-MsiProductCodeFromCommand -ErrorAction SilentlyContinue) {
            Get-MsiProductCodeFromCommand -UninstallCommand $rawCmd -FallbackId $AppEntry.Id
        } else {
            $AppEntry.Id
        }
        $msiArgs = if ($AutoSilent) { "/x `"$msiId`" /qn /norestart" } else { "/x `"$msiId`"" }
        return [PSCustomObject]@{
            Mode                = "MSI"
            Exe                 = "msiexec.exe"
            Args                = $msiArgs
            MsiId               = $msiId
            Framework           = "MSI"
            AddedSilentFlags    = [bool]$AutoSilent
            IsSilent            = [bool]$AutoSilent
            IsLikelyDarkPattern = $false
        }
    }

    $cmdParts = if (Get-Command Split-CommandLineExecutableAndArgs -ErrorAction SilentlyContinue) {
        Split-CommandLineExecutableAndArgs -CommandLine $rawCmd
    } else {
        $spParts = $rawCmd -split '\s+', 2
        [PSCustomObject]@{ Exe = $spParts[0].Trim('"'); Args = if ($spParts.Count -gt 1) { $spParts[1] } else { "" } }
    }

    $exe = [string]$cmdParts.Exe
    $origArgs = if ($null -eq $cmdParts.Args) { "" } else { ([string]$cmdParts.Args).Trim() }
    $missingExe = ($exe -match '^[A-Za-z]:\\') -and (-not [System.IO.File]::Exists($exe))
    if ($missingExe) {
        return [PSCustomObject]@{
            Mode                = "MissingExe"
            Exe                 = $exe
            Args                = $origArgs
            Framework           = ""
            AddedSilentFlags    = $false
            IsSilent            = $false
            IsLikelyDarkPattern = $false
        }
    }

    $framework = ""
    $newArgs = $origArgs
    $addedFlags = $false
    $isSilent = $false

    if ($AutoSilent) {
        $deepType = "DuckUtil.DeepUninstallerEngine" -as [type]
        if ($deepType -and $null -ne $deepType.GetMethod("DetectInstallerFramework")) {
            $framework = [string]$deepType::DetectInstallerFramework($exe)
        }

        switch ($framework) {
            "InnoSetup" {
                if ($newArgs -match '(?i)(^|\s)/VERYSILENT(\s|$)') {
                    $isSilent = $true
                } elseif ($newArgs -match '(?i)(^|\s)/SILENT(\s|$)') {
                    $newArgs = [regex]::Replace($newArgs, '(?i)(?<=^|\s)/SILENT(?=\s|$)', '/VERYSILENT')
                    $addedFlags = $true
                    $isSilent = $true
                } else {
                    $newArgs = "$newArgs /VERYSILENT".Trim()
                    $addedFlags = $true
                    $isSilent = $true
                }
                if ($newArgs -notmatch '(?i)(^|\s)/SUPPRESSMSGBOXES(\s|$)') {
                    $newArgs = "$newArgs /SUPPRESSMSGBOXES".Trim()
                    $addedFlags = $true
                }
                if ($newArgs -notmatch '(?i)(^|\s)/NORESTART(\s|$)') {
                    $newArgs = "$newArgs /NORESTART".Trim()
                    $addedFlags = $true
                }
            }
            "NSIS" {
                if ($newArgs -cmatch '(^|\s)/S(\s|$)' -or $newArgs -match '(?i)(^|\s)(--silent|/silent)(\s|$)') {
                    $isSilent = $true
                } elseif ($newArgs -cmatch '(^|\s)/s(\s|$)') {
                    $newArgs = [regex]::Replace($newArgs, '(?<=^|\s)/s(?=\s|$)', '/S')
                    $addedFlags = $true
                    $isSilent = $true
                } else {
                    $newArgs = "$newArgs /S".Trim()
                    $addedFlags = $true
                    $isSilent = $true
                }
            }
            "WiX" {
                if ($newArgs -match '(?i)(^|\s)(/q|/quiet|/silent|/passive)(\s|$)') {
                    $isSilent = $true
                } else {
                    if ($newArgs -notmatch '(?i)(^|\s)(/uninstall|/x)(\s|$)') {
                        $newArgs = "$newArgs /uninstall".Trim()
                    }
                    $newArgs = "$newArgs /quiet /norestart".Trim()
                    $addedFlags = $true
                    $isSilent = $true
                }
            }
            "BitRock" {
                if ($newArgs -match '(?i)(^|\s)--mode(\s|=)(unattended|minimal)(\s|$)') {
                    $isSilent = $true
                } elseif ($newArgs -notmatch '(?i)(^|\s)--mode(\s|=|$)') {
                    $newArgs = "$newArgs --mode unattended".Trim()
                    $addedFlags = $true
                    $isSilent = $true
                }
            }
            "Squirrel" {
                if ($newArgs -match '(?i)(^|\s)(-s|--silent)(\s|$)') {
                    $isSilent = $true
                } elseif ($newArgs -match '(?i)--uninstall') {
                    $newArgs = "$newArgs -s".Trim()
                    $addedFlags = $true
                    $isSilent = $true
                }
            }
            default {
                $exeBase = [System.IO.Path]::GetFileName($exe)
                if ($exeBase -ieq "setup.exe" -and $newArgs -match '(?i)--uninstall' -and $newArgs -notmatch '(?i)--force-uninstall') {
                    $framework = "ChromiumSetup"
                    $newArgs = "$newArgs --force-uninstall".Trim()
                    $addedFlags = $true
                    $isSilent = $true
                } elseif ($hasExplicitQuiet -or ($newArgs -match '(?i)(^|\s)(/s|/silent|/verysilent|/quiet|/qn|--silent|--quiet|-silent|-s)(\s|$)')) {
                    $isSilent = $true
                }
            }
        }
    } else {
        if ($usedExplicitQuietFallback -or ($newArgs -match '(?i)(^|\s)(/s|/silent|/verysilent|/quiet|/qn|--silent|--quiet|-silent|-s)(\s|$)')) {
            $isSilent = $true
        }
    }

    $hintMeta = "$($AppEntry.DisplayName) $($AppEntry.Publisher) $exe"
    $isDark = ($hintMeta -match '(?i)\b(360Safe|360 Total|Qihu|2345|Kingsoft|Sogou|Baidu|Driver Booster|IObit)\b')

    return [PSCustomObject]@{
        Mode                = "Exe"
        Exe                 = $exe
        Args                = $newArgs
        Framework           = $framework
        AddedSilentFlags    = $addedFlags
        IsSilent            = $isSilent
        IsLikelyDarkPattern = $isDark
    }
}

function Invoke-DeepAppUninstall {
    param(
        [Parameter(Mandatory = $true)]$AppEntry,
        [Parameter(Mandatory = $false)]$OwnerWindow,
        [switch]$SkipVendorUninstaller,
        [switch]$ForceStopAndDelete,
        [bool]$AutoSilent = $true,
        [object[]]$AllInstalledApps = $null,
        [switch]$DeferLeftoverDialog,
        [System.Collections.Generic.List[object]]$CollectedLeftoversOut = $null,
        [switch]$AllowCancel
    )

    if ($ForceStopAndDelete) {
        $SkipVendorUninstaller = $true
    }
    if ($script:isWindowClosing -or ($AllowCancel -and $script:cancelRequested)) { return }

    if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
        Log-Text "=========================================================="
        if ($ForceStopAndDelete) {
            Log-Text "B$([char]0x1EAE)T $([char]0x0110)$([char]0x1EA6)U BU$([char]0x1ED8)C D$([char]0x1EEA)NG & X$([char]0x00D3)A TR$([char]0x1EF0)C TI$([char]0x1EBE)P: $($AppEntry.DisplayName)"
        } else {
            Log-Text "B$([char]0x1EAE)T $([char]0x0110)$([char]0x1EA6)U G$([char]0x1EE0) C$([char]0x00C0)I $([char]0x0110)$([char]0x1EB6)T: $($AppEntry.DisplayName)"
        }
        Log-Text "=========================================================="
    }

    $canWaitNonBlocking = ($null -ne (Get-Command "Wait-TaskNonBlocking" -ErrorAction SilentlyContinue))
    $deepEngT = "DuckUtil.DeepUninstallerEngine" -as [type]
    if ($deepEngT -and $null -ne $deepEngT.GetMethod("PrewarmElevationCache")) {
        try { [DuckUtil.DeepUninstallerEngine]::PrewarmElevationCache() } catch {}
    }

    $allInstalledNow = if ($AllInstalledApps -and $AllInstalledApps.Count -gt 0) {
        $AllInstalledApps
    } elseif ($canWaitNonBlocking -and $deepEngT -and $null -ne $deepEngT.GetMethod("GetInstalledAppsAsync")) {
        $appsTask = $deepEngT::GetInstalledAppsAsync()
        [void](Wait-TaskNonBlocking -Task $appsTask -TimeoutSeconds 45)
        if ($appsTask.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion) {
            @($appsTask.Result)
        } else {
            Get-SystemInstalledAppsFast
        }
    } else {
        Get-SystemInstalledAppsFast
    }
    if ($script:isWindowClosing -or ($AllowCancel -and $script:cancelRequested)) { return }

    $safeLoc = ""
    if ($AppEntry.InstallLocation -and (Test-Path -LiteralPath $AppEntry.InstallLocation)) {
        $loc = try { (Resolve-Path -LiteralPath $AppEntry.InstallLocation).Path.TrimEnd('\') } catch { $AppEntry.InstallLocation.Trim().TrimEnd('\') }
        if (Test-SafeAppDirectoryForCleanup -Path $loc -AppEntry $AppEntry -AllInstalledApps $allInstalledNow) {
            $safeLoc = $loc
            [void](Invoke-ForceStopPathLockers -TargetPath $loc -IncludeServicesAndTasks:$true)
        }
    }
    if ($script:isWindowClosing -or ($AllowCancel -and $script:cancelRequested)) { return }

    if (-not $AppEntry.IsBrokenOrphan) {
        if ($SkipVendorUninstaller) {
            if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
                Log-Text "[FORCE] B$([char]0x1ECF) qua tr$([char]0x00EC)nh g$([char]0x1EE1) c$([char]0x1EE7)a h$([char]0x00E3)ng ($([char]0x0111)$([char]0x00E3) t$([char]0x1EAF)t service/ti$([char]0x1EBF)n tr$([char]0x00EC)nh) -> qu$([char]0x00E9)t x$([char]0x00F3)a s$([char]0x1EA1)ch tr$([char]0x1EF1)c ti$([char]0x1EBF)p."
            }
        } else {
            $plan = Resolve-SilentUninstallPlan -AppEntry $AppEntry -AutoSilent:$AutoSilent
            if ($plan.Mode -eq "MSI") {
                if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
                    if ($AutoSilent) {
                        Log-Text "[*] $([char]0x0110)ang g$([char]0x1ECD)i Windows Installer g$([char]0x1EE1) b$([char]0x1ECF) g$([char]0x00F3)i MSI: $($AppEntry.DisplayName) ($($plan.MsiId))..."
                    } else {
                        Log-Text "[*] $([char]0x0110)ang g$([char]0x1ECD)i Windows Installer g$([char]0x1EE1) b$([char]0x1ECF) g$([char]0x00F3)i MSI (giao di$([char]0x1EC7)n chu$([char]0x1EA9)n): $($AppEntry.DisplayName) ($($plan.MsiId))..."
                    }
                }
                if (Get-Command Run-CliStream -ErrorAction SilentlyContinue) {
                    $msiCode = Run-CliStream "msiexec.exe" $plan.Args -IsolateStdin:($AutoSilent -or $plan.IsSilent) -AllowCancel:$AllowCancel
                    if ($msiCode -eq 1618 -and -not ($AllowCancel -and $script:cancelRequested) -and -not $script:isWindowClosing) {
                        if ($canWaitNonBlocking) {
                            $cancelCb = if ($AllowCancel) { { [bool]$script:cancelRequested } } else { $null }
                            [void](Wait-TaskNonBlocking -Task ([System.Threading.Tasks.Task]::Delay(3000)) -TimeoutSeconds 5 -CancelCheck $cancelCb)
                        } else {
                            Start-Sleep -Seconds 3
                        }
                        if (-not $script:isWindowClosing -and -not ($AllowCancel -and $script:cancelRequested)) {
                            $null = Run-CliStream "msiexec.exe" $plan.Args -IsolateStdin:($AutoSilent -or $plan.IsSilent) -AllowCancel:$AllowCancel
                        }
                    }
                } else {
                    Start-Process "msiexec.exe" -ArgumentList $plan.Args -Wait -NoNewWindow
                }
            } elseif ($plan.Mode -eq "MissingExe") {
                if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
                    Log-Text "[!] Kh$([char]0x00F4)ng t$([char]0x00EC)m th$([char]0x1EA5)y tr$([char]0x00EC)nh g$([char]0x1EE1) g$([char]0x1ED1)c t$([char]0x1EA1)i '$($plan.Exe)' - chuy$([char]0x1EC3)n sang qu$([char]0x00E9)t d$([char]0x1ECD)n s$([char]0x1EA1)ch tr$([char]0x1EF1)c ti$([char]0x1EBF)p."
                }
            } elseif ($plan.Mode -eq "Exe") {
                if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
                    if ($AutoSilent -and $plan.AddedSilentFlags) {
                        Log-Text "[SILENT] Nh$([char]0x1EAD)n di$([char]0x1EC7)n [$($plan.Framework)], $([char]0x0111)$([char]0x00E3) g$([char]0x1EAF)n c$([char]0x1EDD) g$([char]0x1EE1) im l$([char]0x1EB7)ng: $($plan.Exe) $($plan.Args)"
                    } elseif (-not $AutoSilent) {
                        Log-Text "[*] $([char]0x0110)ang th$([char]0x1EF1)c thi tr$([char]0x00EC)nh g$([char]0x1EE1) b$([char]0x1ECF) ch$([char]0x00ED)nh th$([char]0x1EE9)c (t$([char]0x1EAF)t t$([char]0x1EF1) $([char]0x0111)$([char]0x1ED9)ng g$([char]0x1EAF)n c$([char]0x1EDD) im l$([char]0x1EB7)ng): $($plan.Exe) $($plan.Args)"
                    } else {
                        Log-Text "[*] $([char]0x0110)ang th$([char]0x1EF1)c thi tr$([char]0x00EC)nh g$([char]0x1EE1) b$([char]0x1ECF) ch$([char]0x00ED)nh th$([char]0x1EE9)c: $($plan.Exe) $($plan.Args)"
                        if (-not $plan.IsSilent) {
                            $hintText = if ($plan.IsLikelyDarkPattern) {
                                "[!] $([char]0x1EE8)ng d$([char]0x1EE5)ng n$([char]0x00E0)y hay c$([char]0x00F3) b$([char]0x1EA3)ng h$([char]0x1ECF)i gi$([char]0x1EEF) ch$([char]0x00E2)n; n$([char]0x1EBF)u popup hi$([char]0x1EC7)n l$([char]0x00EA)n, l$([char]0x1EA7)n sau h$([char]0x00E3)y t$([char]0x00ED)ch 'B$([char]0x1ECF) qua tr$([char]0x00EC)nh g$([char]0x1EE1) h$([char]0x00E3)ng'."
                            } else {
                                "[!] Kh$([char]0x00F4)ng r$([char]0x00F5) c$([char]0x1EDD) im l$([char]0x1EB7)ng chu$([char]0x1EA9)n cho tr$([char]0x00EC)nh g$([char]0x1EE1) n$([char]0x00E0)y; n$([char]0x1EBF)u c$([char]0x00F3) b$([char]0x1EA3)ng h$([char]0x1ECF)i l$([char]0x00E0)m phi$([char]0x1EC1)n, c$([char]0x00F3) th$([char]0x1EC3) t$([char]0x00ED)ch 'B$([char]0x1ECF) qua tr$([char]0x00EC)nh g$([char]0x1EE1) h$([char]0x00E3)ng'."
                            }
                            Log-Text $hintText
                        }
                    }
                }
                if (Get-Command Run-CliStream -ErrorAction SilentlyContinue) {
                    $null = Run-CliStream $plan.Exe $plan.Args -IsolateStdin:($AutoSilent -and $plan.IsSilent) -AllowCancel:$AllowCancel
                } else {
                    Start-Process $plan.Exe -ArgumentList $plan.Args -Wait -NoNewWindow
                }
            }
        }
    }

    if ($script:isWindowClosing -or ($AllowCancel -and $script:cancelRequested)) { return }
    if ($canWaitNonBlocking) {
        $cancelCb2 = if ($AllowCancel) { { [bool]$script:cancelRequested } } else { $null }
        [void](Wait-TaskNonBlocking -Task ([System.Threading.Tasks.Task]::Delay(800)) -TimeoutSeconds 3 -CancelCheck $cancelCb2)
    } else {
        Start-Sleep -Milliseconds 800
    }
    if ($script:isWindowClosing -or ($AllowCancel -and $script:cancelRequested)) { return }

    if ($safeLoc -and (Test-Path -LiteralPath $safeLoc)) {
        [void](Invoke-ForceStopPathLockers -TargetPath $safeLoc -IncludeServicesAndTasks:$true)
    }
    if ($script:isWindowClosing -or ($AllowCancel -and $script:cancelRequested)) { return }

    $leftovers = Find-AppLeftovers -AppEntry $AppEntry -AllInstalledApps $allInstalledNow
    if ($script:isWindowClosing -or ($AllowCancel -and $script:cancelRequested)) { return }

    if ($DeferLeftoverDialog) {
        if ($leftovers.Count -gt 0) {
            if ($null -ne $CollectedLeftoversOut) {
                foreach ($lo in $leftovers) { $CollectedLeftoversOut.Add($lo) }
            }
            if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
                Log-Text "[*] $([char]0x0110)$([char]0x00E3) ghi nh$([char]0x1EAD)n $($leftovers.Count) m$([char]0x1EE5)c r$([char]0x00E1)c t$([char]0x1ED3)n d$([char]0x01B0) c$([char]0x1EE7)a '$($AppEntry.DisplayName)' (s$([char]0x1EBD) m$([char]0x1EDF) h$([char]0x1ED9)p tho$([char]0x1EA1)i d$([char]0x1ECD)n cu$([char]0x1ED1)i h$([char]0x00E0)ng $([char]0x0111)$([char]0x1EE3)i)."
            }
        } else {
            if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
                Log-Text "[OK] '$($AppEntry.DisplayName)' $([char]0x0111)$([char]0x00E3) s$([char]0x1EA1)ch s$([char]0x1EBD), kh$([char]0x00F4)ng ph$([char]0x00E1)t hi$([char]0x1EC7)n r$([char]0x00E1)c t$([char]0x1ED3)n d$([char]0x01B0)."
            }
        }
        return
    }

    if ($leftovers.Count -gt 0) {
        if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
            Log-Text "[*] Ph$([char]0x00E1)t hi$([char]0x1EC7)n $($leftovers.Count) m$([char]0x1EE5)c r$([char]0x00E1)c / Registry c$([char]0x00F2)n s$([char]0x00F3)t l$([char]0x1EA1)i sau khi g$([char]0x1EE1) b$([char]0x1ECF)."
        }
        $dialogTitle = "D$([char]0x1ECD)n r$([char]0x00E1)c t$([char]0x1ED3)n d$([char]0x01B0) sau khi g$([char]0x1EE1): $($AppEntry.DisplayName)"
        $res = Show-LeftoverReviewDialog -OwnerWindow $OwnerWindow -Items $leftovers -Title $dialogTitle -ForceStopByDefault:$true
        if ($res.Confirmed) {
            if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
                $freedMb = [math]::Round($res.FreedBytes / 1MB, 2)
                Log-Text "[OK] $([char]0x0110)$([char]0x00E3) d$([char]0x1ECD)n s$([char]0x1EA1)ch $($res.RemovedCount) m$([char]0x1EE5)c t$([char]0x1ED3)n d$([char]0x01B0) (~$freedMb MB)."
            }
        }
    } else {
        if (Get-Command Log-Text -ErrorAction SilentlyContinue) {
            Log-Text "[OK] Tr$([char]0x00EC)nh g$([char]0x1EE1) b$([char]0x1ECF) $([char]0x0111)$([char]0x00E3) d$([char]0x1ECD)n d$([char]0x1EB9)p s$([char]0x1EA1)ch s$([char]0x1EBD), kh$([char]0x00F4)ng ph$([char]0x00E1)t hi$([char]0x1EC7)n r$([char]0x00E1)c t$([char]0x1ED3)n d$([char]0x01B0)."
        }
    }
}

function Find-FaultyPnpDevices {
    try {
        return @(Get-PnpDevice -ErrorAction Stop | Where-Object {
            $_.Present -eq $true -and ($_.Status -ne 'OK' -or ($null -ne $_.ConfigManagerErrorCode -and $_.ConfigManagerErrorCode -ne 0))
        })
    } catch {
        Log-Text "[!] L$([char]0x1ED7)i khi qu$([char]0x00E9)t danh s$([char]0x00E1)ch PnpDevice: $($_.Exception.Message)"
        return @()
    }
}

